window.RF_FULL=window.RF_FULL||{};window.RF_FULL["fz30sudsoob"]=[
["0","Преамбула и список изменений","","2026-05-02","РОССИЙСКАЯ ФЕДЕРАЦИЯ ФЕДЕРАЛЬНЫЙ ЗАКОН Об органах судейского сообщества в Российской Федерации\nПринят Государственной Думой 15 февраля 2002 года\nОдобрен Советом Федерации 27 февраля 2002 года\nСписок изменяющих документов(В редакции федеральных законов от 04.07.2003 № 96-ФЗ, от 14.08.2004 № 100-ФЗ, от 05.04.2005 № 33-ФЗ, от 25.12.2008 № 274-ФЗ, от 17.07.2009 № 157-ФЗ, от 24.07.2009 № 210-ФЗ, от 09.11.2009 № 246-ФЗ, от 28.11.2009 № 296-ФЗ, от 08.12.2010 № 346-ФЗ, от 03.12.2011 № 388-ФЗ, от 02.10.2012 № 165-ФЗ, от 04.03.2013 № 20-ФЗ, от 02.07.2013 № 185-ФЗ, от 12.03.2014 № 29-ФЗ, от 06.04.2015 № 69-ФЗ, от 08.06.2015 № 144-ФЗ, от 05.10.2015 № 284-ФЗ, от 02.06.2016 № 168-ФЗ, от 18.04.2018 № 76-ФЗ, от 29.07.2018 № 243-ФЗ, от 29.07.2018 № 266-ФЗ, от 03.07.2019 № 163-ФЗ, от 26.07.2019 № 197-ФЗ, от 20.07.2020 № 231-ФЗ, от 08.12.2020 № 426-ФЗ, от 13.12.2024 № 466-ФЗ, от 23.07.2025 № 256-ФЗ, от 02.05.2026 № 122-ФЗ)"],
["1","Судейское сообщество в Российской Федерации","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","","Статья 1. Судейское сообщество в Российской Федерации\nСудейское сообщество в Российской Федерации (далее - судейское сообщество) образуют судьи федеральных судов всех видов и уровней, судьи судов субъектов Российской Федерации, составляющих судебную систему Российской Федерации."],
["2","Судья - член судейского сообщества","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","","Статья 2. Судья - член судейского сообщества\n1. Судьи федеральных судов и судов субъектов Российской Федерации являются членами судейского сообщества с момента принесения ими присяги судьи и до момента вступления в силу решения о прекращении полномочий судьи, за исключением случая прекращения полномочий в связи с почетным уходом или почетным удалением судьи в отставку.\n2. Судья, пребывающий в отставке, сохраняет свою принадлежность к судейскому сообществу до прекращения отставки и может привлекаться с его согласия к работе в органах судейского сообщества. Судья, пребывающий в отставке, не вправе избирать членов квалификационных коллегий судей и быть избранным в состав квалификационных коллегий судей от судейского сообщества."],
["3","Органы судейского сообщества","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2011-12-03","Статья 3. Органы судейского сообщества\n1. Органы судейского сообщества формируются и действуют в соответствии с федеральными конституционными законами и федеральными законами для выражения интересов судей как носителей судебной власти.\n2. Органами судейского сообщества в Российской Федерации являются:\nВсероссийский съезд судей;\nконференции судей субъектов Российской Федерации;\nСовет судей Российской Федерации;\nсоветы судей субъектов Российской Федерации;\nобщие собрания судей судов;\nВысшая квалификационная коллегия судей Российской Федерации;\nквалификационные коллегии судей субъектов Российской Федерации;\nВысшая экзаменационная комиссия по приему квалификационного экзамена на должность судьи; (Дополнение абзацем - Федеральный закон от 03.12.2011 № 388-ФЗ)\nэкзаменационные комиссии субъектов Российской Федерации по приему квалификационного экзамена на должность судьи. (Дополнение абзацем - Федеральный закон от 03.12.2011 № 388-ФЗ)\n3. Деятельность органов судейского сообщества регулируется актами (регламентами, положениями), принимаемыми этими органами.\n4. В Верховном Суде Российской Федерации формируются общее собрание судей Верховного Суда Российской Федерации и Совет судей Верховного Суда Российской Федерации, полномочия, порядок формирования и деятельности которых регулируются положением, принимаемым общим собранием судей Верховного Суда Российской Федерации. (Дополнение пунктом - Федеральный закон от 08.12.2010 № 346-ФЗ)"],
["4","Основные задачи органов судейского сообщества","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","","Статья 4. Основные задачи органов судейского сообщества\nОсновными задачами органов судейского сообщества являются:\n1) содействие в совершенствовании судебной системы и судопроизводства;\n2) защита прав и законных интересов судей;\n3) участие в организационном, кадровом и ресурсном обеспечении судебной деятельности;\n4) утверждение авторитета судебной власти, обеспечение выполнения судьями требований, предъявляемых кодексом судейской этики."],
["5","Принципы организации и деятельности органов судейского сообщества","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2011-12-03","Статья 5. Принципы организации и деятельности органов судейского сообщества\n1. Органы судейского сообщества осуществляют свою деятельность коллегиально, гласно, при неукоснительном соблюдении принципов независимости судей и невмешательства в судебную деятельность.\n2. Советы судей, квалификационные коллегии судей, Высшая экзаменационная комиссия по приему квалификационного экзамена на должность судьи и экзаменационные комиссии субъектов Российской Федерации по приему квалификационного экзамена на должность судьи (далее также - экзаменационные комиссии) формируются на принципах выборности, сменяемости и подотчетности органам, их избравшим. Квалификационные коллегии судей и экзаменационные комиссии не подотчетны органам, их избравшим, за принятые решения. (В редакции Федерального закона от 03.12.2011 № 388-ФЗ)"],
["6","Всероссийский съезд судей","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2026-05-02","Статья 6. Всероссийский съезд судей\n1. Всероссийский съезд судей (далее также - съезд) является высшим органом судейского сообщества.\nСъезд правомочен принимать решения по всем вопросам, относящимся к деятельности судейского сообщества, за исключением вопросов, относящихся к полномочиям квалификационных коллегий судей и экзаменационных комиссий, а также правомочен утверждать кодекс судейской этики и акты, регулирующие деятельность судейского сообщества. Решения съезда принимаются простым большинством голосов, если съездом не устанавливается иной порядок принятия решений. (В редакции Федерального закона от 03.12.2011 № 388-ФЗ)\n2. Делегаты на съезд избираются по следующим нормам представительства:\nот судей Конституционного Суда Российской Федерации - десять судей;\nот судей Верховного Суда Российской Федерации - двадцать судей;\nот судей каждого кассационного суда общей юрисдикции, кассационного военного суда - по два судьи; (Дополнение абзацем - Федеральный закон от 29.07.2018 № 266-ФЗ)\nот судей каждого апелляционного суда общей юрисдикции, апелляционного военного суда - по два судьи; (Дополнение абзацем - Федеральный закон от 29.07.2018 № 266-ФЗ)\nот судей каждого арбитражного суда округа, Суда по интеллектуальным правам - по два судьи; (В редакции Федерального закона от 20.07.2020 № 231-ФЗ)\nот судей каждого арбитражного апелляционного суда - по два судьи;\nот судей каждого верховного суда республики, краевого, областного суда, суда города федерального значения, суда автономной области и суда автономного округа - по одному судье, а также дополнительно по одному судье от каждых пятидесяти судей каждого верховного суда республики, краевого, областного суда, суда города федерального значения, суда автономной области и суда автономного округа;\nот судей каждого арбитражного суда субъекта Российской Федерации - по одному судье, а также дополнительно по одному судье от каждых тридцати судей каждого арбитражного суда субъекта Российской Федерации;\nот судей каждого окружного (флотского) военного суда - по два судьи;\nот судей гарнизонных военных судов - по одному судье от каждого субъекта Российской Федерации, на территории которого действуют гарнизонные военные суды;\nот судей районных судов - по одному судье от каждого субъекта Российской Федерации, а также дополнительно по одному судье от каждых ста судей районных судов, действующих на территории субъекта Российской Федерации;\nот мировых судей - по одному судье от каждого субъекта Российской Федерации;\nабзац. (Утратил силу - Федеральный закон от 08.12.2020 № 426-ФЗ)\n(Пункт в редакции Федерального закона от 12.03.2014 № 29-ФЗ)\n3. Делегаты на съезд от судей Конституционного Суда Российской Федерации, Верховного Суда Российской Федерации, кассационных судов общей юрисдикции, апелляционных судов общей юрисдикции, кассационного военного суда, апелляционного военного суда, арбитражных судов округов, Суда по интеллектуальным правам, арбитражных апелляционных судов, окружных (флотских) военных судов избираются на общих собраниях судей этих судов, а делегаты от судей иных судов - на конференциях судей субъектов Российской Федерации. (В редакции федеральных законов от 14.08.2004 № 100-ФЗ, от 12.03.2014 № 29-ФЗ, от 29.07.2018 № 266-ФЗ, от 20.07.2020 № 231-ФЗ)\nСъезд созывается один раз в шесть лет Советом судей Российской Федерации. При угрозе возникновения и (или) возникновении отдельных чрезвычайных ситуаций, введении режима повышенной готовности или чрезвычайной ситуации на всей территории Российской Федерации либо на ее части, возникновении иных ситуаций, исключающих возможность проведения очередного съезда, созыв съезда может быть перенесен по решению Совета судей Российской Федерации на более поздний срок. Внеочередной съезд должен быть созван, если решение об этом принято конференциями судей не менее чем в половине субъектов Российской Федерации. (В редакции федеральных законов от 20.07.2020 № 231-ФЗ, от 02.05.2026 № 122-ФЗ)\nСъезд считается правомочным, если в его работе принимают участие более половины избранных делегатов.\nПредседательствует на съезде председатель Совета судей Российской Федерации."],
["7","Конференции судей субъектов Российской Федерации","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2020-12-08","Статья 7. Конференции судей субъектов Российской Федерации\n1. Конференции судей субъектов Российской Федерации (далее также - конференции судей) представляют судей верховных судов республик, краевых, областных судов, судов городов федерального значения, суда автономной области и судов автономных округов, арбитражных судов субъектов Российской Федерации, а также мировых судей, судей районных судов и гарнизонных военных судов, действующих на территориях соответствующих субъектов Российской Федерации. (В редакции Федерального закона от 08.12.2020 № 426-ФЗ)\nКонференции судей правомочны принимать решения по всем вопросам, относящимся к деятельности судейского сообщества в субъектах Российской Федерации, за исключением вопросов, относящихся к полномочиям квалификационных коллегий судей и экзаменационных комиссий, а также правомочны утверждать акты, регулирующие деятельность органов судейского сообщества в субъектах Российской Федерации. Решения конференций судей принимаются простым большинством голосов, если конференциями не устанавливается иной порядок принятия решений. (В редакции Федерального закона от 03.12.2011 № 388-ФЗ)\n2. Конференции судей созываются советом судей соответствующего субъекта Российской Федерации по мере необходимости, но не реже одного раза в два года.\nПорядок избрания делегатов на первую после вступления в силу настоящего Федерального закона конференцию судей и нормы их представительства от соответствующих судов утверждаются советом судей соответствующего субъекта Российской Федерации, на последующие конференции судей - конференцией судей.\nДелегаты на конференции судей избираются с учетом необходимости представительства на них судей соответственно от верховных судов республик, краевых, областных судов, судов городов федерального значения, суда автономной области и судов автономных округов, арбитражных судов субъектов Российской Федерации, а также от мировых судей, судей районных судов и судей гарнизонных военных судов, действующих на территориях соответствующих субъектов Российской Федерации. (В редакции Федерального закона от 08.12.2020 № 426-ФЗ)\nПредседательствует на конференции судей председатель совета судей соответствующего субъекта Российской Федерации."],
["8","Формирование советов судей","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2020-12-08","Статья 8. Формирование советов судей\n1. Совет судей Российской Федерации формируется Всероссийским съездом судей из числа судей федеральных судов и мировых судей. (В редакции Федерального закона от 08.12.2020 № 426-ФЗ)\nВ Совете судей Российской Федерации устанавливаются следующие нормы представительства:\nот судей Конституционного Суда Российской Федерации - два судьи;\nот судей Верховного Суда Российской Федерации - четыре судьи;\nот судей кассационных судов общей юрисдикции - семь судей;\nот судей кассационного военного суда - один судья;\nот судей апелляционных судов общей юрисдикции - два судьи;\nот судей апелляционного военного суда - один судья;\nот судей арбитражных судов округов - четыре судьи;\nот судей Суда по интеллектуальным правам - один судья;\nот судей арбитражных апелляционных судов - шесть судей;\nот судей верховных судов республик, краевых, областных судов, судов городов федерального значения, суда автономной области и судов автономных округов - пять судей;\nот судей арбитражных судов субъектов Российской Федерации - восемь судей;\nот судей окружных (флотских) военных судов - два судьи;\nот судей гарнизонных военных судов - три судьи;\nот судей районных судов - восемь судей;\nот мировых судей - пять судей;\nабзац; (Утратил силу - Федеральный закон от 08.12.2020 № 426-ФЗ)\nот каждого субъекта Российской Федерации - по одному судье, избираемому съездом по представлению соответствующей конференции судей субъекта Российской Федерации.\n(Пункт в редакции Федерального закона от 20.07.2020 № 231-ФЗ)\n2. Члены Совета судей Российской Федерации, представляющие судей судов всех видов и уровней, избираются тайным голосованием делегатами съезда от соответствующих судов из своего состава на раздельных собраниях делегатов. Избранными считаются судьи, получившие на раздельных собраниях делегатов наибольшее число голосов делегатов съезда, принявших участие в голосовании, при условии, что в голосовании принимали участие более половины делегатов съезда от соответствующих судов.\nЧлены Совета судей Российской Федерации, представляемые конференциями судей, избираются тайным голосованием делегатами съезда. Избранными считаются судьи, получившие большинство голосов делегатов съезда, принявших участие в голосовании.\n3. Совет судей Российской Федерации избирает из своего состава подотчетных ему председателя Совета судей Российской Федерации и его заместителей.\nАбзац. (Утратил силу - Федеральный закон от 05.10.2015 № 284-ФЗ)\nПрезидиум Совета судей Российской Федерации избирается Советом судей Российской Федерации из числа его членов с учетом необходимости представительства в нем судей федеральных судов, в том числе судей Конституционного Суда Российской Федерации, судей Верховного Суда Российской Федерации, судей судов общей юрисдикции, включая военные суды, судей арбитражных судов и судей судов субъектов Российской Федерации. В состав Президиума Совета судей Российской Федерации входят по должности председатель Совета судей Российской Федерации и его заместители. (В редакции Федерального закона от 12.03.2014 № 29-ФЗ)\n4. Советы судей субъектов Российской Федерации избираются конференциями судей в количестве и порядке, которые определяются конференциями судей в соответствии с их регламентами с учетом необходимости представительства в них судей соответственно от верховных судов республик, краевых, областных судов, судов городов федерального значения, суда автономной области и судов автономных округов, арбитражных судов субъектов Российской Федерации, а также от мировых судей, судей районных судов и гарнизонных военных судов, действующих на территориях соответствующих субъектов Российской Федерации. (В редакции Федерального закона от 08.12.2020 № 426-ФЗ)\nСовет судей субъектов Российской Федерации избирает из своего состава подотчетных ему председателя совета судей субъекта Российской Федерации и его заместителей.\nЧлен совета судей субъекта Российской Федерации не может быть избран на должность председателя совета судей субъекта Российской Федерации или заместителя председателя совета судей субъекта Российской Федерации более двух раз подряд.\n5. Полномочия члена совета судей могут быть досрочно прекращены по его инициативе или в случае совершения им дисциплинарного проступка. Решение о досрочном прекращении полномочий членов советов судей принимается соответственно съездом или конференцией судей, а в период между съездами (конференциями) судей - соответствующим советом судей."],
["9","Совет судей Российской Федерации как орган судейского сообщества","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2020-07-20","Статья 9. Совет судей Российской Федерации как орган судейского сообщества\n1. Совет судей Российской Федерации является выборным органом судейского сообщества, подотчетным только съезду.\n2. Совет судей Российской Федерации созывается по мере необходимости, но не реже двух раз в год.\n3. Рабочим органом Совета судей Российской Федерации является Президиум Совета судей Российской Федерации, который создается для оперативного коллегиального решения вопросов, определяемых регламентом Совета судей Российской Федерации.\nЗаседания Президиума Совета судей Российской Федерации проводятся по мере необходимости, но не реже четырех раз в год.\n3.1. Пленарные заседания Совета судей Российской Федерации и заседания Президиума Совета судей Российской Федерации проводятся в порядке, определяемом регламентом Совета судей Российской Федерации. (Дополнение пунктом - Федеральный закон от 20.07.2020 № 231-ФЗ)\n4. Председатель Совета судей Российской Федерации созывает Совет судей Российской Федерации, Президиум Совета судей Российской Федерации и руководит их работой в соответствии с регламентом Совета судей Российской Федерации.\n5. Председатель Совета судей Российской Федерации представляет Совет судей Российской Федерации в органах государственной власти и органах местного самоуправления, в общественных объединениях, средствах массовой информации, а также при осуществлении международного сотрудничества.\n6. По поручению председателя Совета судей Российской Федерации его полномочия может осуществлять один из его заместителей."],
["10","Полномочия советов судей","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2025-07-23","Статья 10. Полномочия советов судей\n1. Совет судей Российской Федерации:\n1) созывает Всероссийский съезд судей;\n2) дает согласие на назначение на должность и освобождение от должности Генерального директора Судебного департамента при Верховном Суде Российской Федерации и заслушивает его годовые отчеты об организационном, кадровом и ресурсном обеспечении судебной деятельности;\n3) избирает судей в состав Высшей квалификационной коллегии судей Российской Федерации вместо выбывших в период между съездами;\n3.1) избирает членов Высшей экзаменационной комиссии по приему квалификационного экзамена на должность судьи (далее также - Высшая экзаменационная комиссия) вместо выбывших в период между съездами; (Дополнение подпунктом - Федеральный закон от 03.12.2011 № 388-ФЗ)\n4) изучает, обобщает и распространяет опыт работы органов судейского сообщества, разрабатывает рекомендации по совершенствованию их деятельности;\n5) определяет порядок участия судей гарнизонных военных судов, действующих за пределами Российской Федерации, в работе органов судейского сообщества субъектов Российской Федерации;\n6) осуществляет иные полномочия, отнесенные к его ведению федеральными законами.\n2. Представители Совета судей Российской Федерации вправе участвовать в обсуждении проекта федерального закона о федеральном бюджете в Федеральном Собрании Российской Федерации.\n3. Совет судей Российской Федерации, а также иные органы судейского сообщества в пределах своей компетенции осуществляют прямые связи с органами судейского сообщества и профессиональными объединениями (ассоциациями) судей других государств, с международными организациями, а также со средствами массовой информации.\n3.1. Совет судей Российской Федерации, Президиум Совета судей Российской Федерации, совет судей субъекта Российской Федерации в случае выявления признаков совершения судьей дисциплинарного проступка вправе провести проверку и направить в квалификационную коллегию судей обращение о наложении на судью дисциплинарного взыскания, в том числе в виде досрочного прекращения полномочий судьи.\nОбращение о наложении на судью дисциплинарного взыскания за совершение дисциплинарного проступка при исполнении судьей служебных обязанностей может быть направлено в квалификационную коллегию судей Советом судей Российской Федерации, иным органом судейского сообщества, указанным в настоящем пункте, только при наличии частного определения, вынесенного вышестоящей судебной инстанцией, либо жалобы или обращения участника (участников) процесса о нарушении его (их) прав незаконными действиями судьи, совершенными при рассмотрении дела.\nСудья информируется о проводимой проверке и вправе участвовать в ней, знакомиться с материалами проверки, представлять письменные объяснения и возражения, а также доказательства, подтверждающие свои объяснения. Отказ судьи от участия в проверке не является препятствием к ее проведению.\n(Дополнение пунктом - Федеральный закон от 29.07.2018 № 243-ФЗ)\n4. Советы судей субъектов Российской Федерации:\n1) рассматривают в период между конференциями судей все вопросы, отнесенные к компетенции конференций судей, за исключением избрания квалификационных коллегий судей субъектов Российской Федерации и заслушивания их отчетов;\n2) созывают конференции судей;\n3) избирают судей в состав квалификационных коллегий судей соответствующих субъектов Российской Федерации вместо выбывших в период между конференциями судей;\n4) избирают членов экзаменационных комиссий субъектов Российской Федерации по приему квалификационного экзамена на должность судьи (далее также - экзаменационные комиссии субъектов Российской Федерации) вместо выбывших в период между конференциями судей; (Дополнение подпунктом - Федеральный закон от 03.12.2011 № 388-ФЗ)\n5) взаимодействуют с высшим исполнительным органом государственной власти субъекта Российской Федерации при разработке проекта бюджета субъекта Российской Федерации в части расходов на материально-техническое обеспечение деятельности мировых судей и оплату труда работников аппарата мировых судей; (Дополнение подпунктом - Федеральный закон от 18.04.2018 № 76-ФЗ)\n5.1) взаимодействуют с органами государственной власти субъекта Российской Федерации при определении структуры и штатного расписания аппарата мирового судьи в порядке, предусмотренном законом субъекта Российской Федерации; (Дополнение подпунктом - Федеральный закон от 23.07.2025 № 256-ФЗ)\n6) ведут списки судей, пребывающих в отставке и изъявивших желание осуществлять деятельность медиаторов на профессиональной основе. (Дополнение подпунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n5. Совет судей Российской Федерации и советы судей субъектов Российской Федерации могут осуществлять свои полномочия, если их составы сформированы не менее чем на две трети."],
["11","Формирование квалификационных коллегий судей","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2024-12-13","Статья 11. Формирование квалификационных коллегий судей\n1. Квалификационные коллегии судей формируются из числа судей федеральных судов, судей судов субъектов Российской Федерации, представителей общественности, представителей Президента Российской Федерации.\n2. Высшая квалификационная коллегия судей Российской Федерации формируется в количестве двадцати девяти членов коллегии.\nЧлены коллегии из числа судей избираются по следующим нормам представительства:\nот судей Верховного Суда Российской Федерации - четыре судьи;\nот судей кассационных судов общей юрисдикции - два судьи;\nот судей апелляционных судов общей юрисдикции - два судьи;\nот судей кассационного, апелляционного военных судов - один судья;\nот судей арбитражных судов округов, Суда по интеллектуальным правам - два судьи; (В редакции Федерального закона от 20.07.2020 № 231-ФЗ)\nот судей арбитражных апелляционных судов - два судьи;\nот судей верховных судов республик, краевых, областных судов, судов городов федерального значения, суда автономной области и судов автономных округов - два судьи;\nот судей арбитражных судов субъектов Российской Федерации - два судьи;\nот судей окружных (флотских) военных судов - один судья.\nДесять членов коллегии - представители общественности назначаются Советом Федерации Федерального Собрания Российской Федерации.\nОдин член коллегии - представитель Президента Российской Федерации назначается Президентом Российской Федерации.\n(Пункт в редакции Федерального закона от 29.07.2018 № 266-ФЗ)\n3. Судьи в состав Высшей квалификационной коллегии судей Российской Федерации избираются тайным голосованием на съезде делегатами съезда от соответствующих судов из своего состава на раздельных собраниях делегатов.\nИзбранными считаются судьи, получившие на раздельных собраниях делегатов наибольшее количество голосов делегатов съезда, принявших участие в голосовании, при условии, что в голосовании принимали участие более половины делегатов съезда от соответствующих судов.\nИзбрание судей в состав Высшей квалификационной коллегии судей Российской Федерации вместо выбывших в период между съездами производится Советом судей Российской Федерации.\n4. Квалификационная коллегия судей субъекта Российской Федерации формируется по следующим нормам представительства:\nот судей верховного суда республики, краевого, областного суда, суда города федерального значения, суда автономной области и суда автономного округа - два судьи;\nот судей арбитражного суда субъекта Российской Федерации - пять судей;\nот судей гарнизонных военных судов - один судья;\nот судей районных судов - три судьи;\nабзац; (Утратил силу - Федеральный закон от 08.12.2020 № 426-ФЗ)\nот мировых судей - один судья;\nсемь представителей общественности;\nодин представитель Президента Российской Федерации.\nВ субъектах Российской Федерации, в которых общая численность судей судов, указанных в абзацах втором - шестом настоящего пункта, менее 30, квалификационная коллегия судей формируется в количестве 11 членов коллегии по следующим нормам представительства:\nот судей верховного суда республики, краевого, областного суда, суда города федерального значения, суда автономной области и суда автономного округа - один судья;\nот судей арбитражного суда субъекта Российской Федерации - два судьи;\nот судей гарнизонных военных судов - один судья;\nот судей районных судов - два судьи;\nабзац; (Утратил силу - Федеральный закон от 08.12.2020 № 426-ФЗ)\nот мировых судей - один судья;\nдва представителя общественности;\nодин представитель Президента Российской Федерации.\nЕсли в субъекте Российской Федерации не образованы верховный суд республики, краевой, областной суд, суд города федерального значения, суд автономной области, суд автономного округа, арбитражный суд субъекта Российской Федерации, не действуют мировые судьи, отсутствуют гарнизонные военные суды, то квалификационная коллегия судей данного субъекта Российской Федерации формируется без участия представителей судей этих судов. При этом нормы представительства, указанные в абзацах втором - восьмом настоящего пункта, сохраняются. (В редакции Федерального закона от 08.12.2020 № 426-ФЗ)\n5. Судьи Арбитражного суда Санкт-Петербурга и Ленинградской области избираются в состав квалификационной коллегии судей и других органов судейского сообщества Санкт-Петербурга.\nКвалификационная коллегия судей Ленинградской области формируется по следующим нормам представительства:\nот судей Ленинградского областного суда - два судьи;\nот судей гарнизонных военных судов - один судья;\nот судей районных судов Ленинградской области - три судьи;\nабзац; (Утратил силу - Федеральный закон от 08.12.2020 № 426-ФЗ)\nот мировых судей - один судья;\nчетыре представителя общественности;\nодин представитель Президента Российской Федерации.\nСудьи районных судов и мировые судьи Эвенкийского автономного округа избираются в состав квалификационной коллегии судей и других органов судейского сообщества Красноярского края.\n6. Судьи в состав квалификационной коллегии судей субъекта Российской Федерации избираются тайным голосованием на конференции судей в порядке, определяемом этой конференцией.\nИзбрание судей в состав квалификационной коллегии судей субъекта Российской Федерации вместо выбывших в период между конференциями производится советом судей субъекта Российской Федерации.\nПредставители общественности в квалификационной коллегии судей субъекта Российской Федерации назначаются законодательным органом субъекта Российской Федерации в порядке, определяемом законами и иными нормативными правовыми актами субъекта Российской Федерации. (В редакции Федерального закона от 13.12.2024 № 466-ФЗ)\nПредставитель Президента Российской Федерации в квалификационной коллегии судей субъекта Российской Федерации назначается Президентом Российской Федерации.\n7. В состав квалификационных коллегий судей субъектов Российской Федерации не могут быть избраны председатели судов и их заместители. В состав Высшей квалификационной коллегии судей Российской Федерации не могут быть избраны Председатель Верховного Суда Российской Федерации и его заместители. (В редакции Федерального закона от 12.03.2014 № 29-ФЗ)\nСудья не может быть избран одновременно в совет судей и квалификационную коллегию судей одного уровня, а также не может быть членом квалификационных коллегий судей разных уровней.\nЧлен квалификационной коллегии судей не может быть избран на должность председателя или заместителя председателя квалификационной коллегии судей более двух раз подряд, за исключением Высшей квалификационной коллегии судей Российской Федерации. (В редакции Федерального закона от 05.10.2015 № 284-ФЗ)\nВ случае прекращения полномочий судьи по основаниям, которые предусмотрены пунктом 1 статьи 14 Закона Российской Федерации от 26 июня 1992 года № 3132-I \"О статусе судей в Российской Федерации\", его полномочия члена квалификационной коллегии судей прекращаются. Полномочия члена квалификационной коллегии судей из числа судей могут быть досрочно прекращены по его инициативе, либо в случае совершения им дисциплинарного проступка, либо в случае его отсутствия на заседаниях квалификационной коллегии судей в течение четырех месяцев без уважительных причин. Решение о досрочном прекращении полномочий членов квалификационной коллегии судей из числа судей принимается съездом (конференцией) судей, а в период между съездами (конференциями) судей - соответствующим советом судей. (В редакции Федерального закона от 08.06.2015 № 144-ФЗ)\n8. Представителями общественности в квалификационных коллегиях судей могут быть граждане Российской Федерации, достигшие 35 лет, имеющие высшее юридическое образование, не совершившие порочащих их поступков, не замещающие государственные или муниципальные должности, должности государственной или муниципальной службы, не являющиеся руководителями организаций и учреждений независимо от организационно-правовых форм и форм собственности, адвокатами и нотариусами.\nПредставитель общественности не вправе иметь гражданство (подданство) иностранного государства либо вид на жительство или иной документ, подтверждающий право на постоянное проживание гражданина Российской Федерации на территории иностранного государства. (Дополнение абзацем - Федеральный закон от 13.12.2024 № 466-ФЗ)\nПредставителем общественности не может быть лицо, включенное в реестр иностранных агентов. (Дополнение абзацем - Федеральный закон от 13.12.2024 № 466-ФЗ)\nПредставителями Президента Российской Федерации в квалификационных коллегиях судей могут быть граждане Российской Федерации, состоящие на государственной службе Российской Федерации. (В редакции Федерального закона от 08.12.2010 № 346-ФЗ)\nПредставитель общественности, представитель Президента Российской Федерации в квалификационной коллегии судей при осуществлении полномочий члена квалификационной коллегии судей, а также во внеслужебных отношениях должны избегать всего, что могло бы умалить авторитет судебной власти или вызвать сомнения в объективности, справедливости и беспристрастности указанных представителей.\nПолномочия члена квалификационной коллегии судей - представителя общественности по решению соответственно Совета Федерации Федерального Собрания Российской Федерации, законодательного органа субъекта Российской Федерации могут быть досрочно прекращены по его инициативе, либо в случае совершения им преступления, установленного вступившим в законную силу приговором суда, в случаях невыполнения им требований, предусмотренных абзацами вторым и пятым настоящего пункта, либо в случае включения лица в реестр иностранных агентов, либо в случае его отсутствия на заседаниях квалификационной коллегии судей в течение четырех месяцев без уважительных причин, либо в случае замещения должности или осуществления деятельности, указанных в абзаце первом настоящего пункта. (В редакции Федерального закона от 13.12.2024 № 466-ФЗ)\nПолномочия члена квалификационной коллегии судей - представителя Президента Российской Федерации прекращаются Президентом Российской Федерации. (В редакции Федерального закона от 08.06.2015 № 144-ФЗ)\n(Пункт в редакции Федерального закона от 04.07.2003 № 96-ФЗ)"],
["11.1","Формирование экзаменационных комиссий по приему квалификационного экзамена на должность судьи","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2016-06-02","Статья 11.1. Формирование экзаменационных комиссий по приему квалификационного экзамена на должность судьи\n1. Высшая экзаменационная комиссия по приему квалификационного экзамена на должность судьи формируется в количестве двадцати одного члена комиссии. Члены комиссии избираются по следующим нормам представительства:\n1) от Верховного Суда Российской Федерации - пять членов комиссии;\n2) от судей судов общей юрисдикции - пять членов комиссии;\n3) от судей арбитражных судов - пять членов комиссии;\n4) от преподавателей юридических дисциплин образовательных организаций высшего образования и научных работников, имеющих ученую степень кандидата юридических наук или доктора юридических наук, - четыре члена комиссии;\n5) от общероссийских общественных объединений юристов - два члена комиссии.\n2. Экзаменационные комиссии субъектов Российской Федерации по приему квалификационного экзамена на должность судьи формируются из числа:\n1) судей судов общей юрисдикции и судей арбитражных судов, при этом в составе соответствующей экзаменационной комиссии число судей судов общей юрисдикции должно быть равным числу судей арбитражных судов и вместе они должны составлять не менее трех четвертей от общего числа членов экзаменационной комиссии;\n2) преподавателей юридических дисциплин образовательных организаций высшего образования, научных работников, имеющих ученую степень кандидата юридических наук или доктора юридических наук, представителей общероссийских общественных объединений юристов, которые осуществляют полномочия членов экзаменационных комиссий на платной основе.\n3. В случае, если на территории субъекта Российской Федерации отсутствует арбитражный суд или невозможно обеспечить равное представительство судей судов общей юрисдикции и судей арбитражных судов в составе экзаменационной комиссии субъекта Российской Федерации в связи с недостаточной численностью судей арбитражных судов, такое представительство определяется регламентом экзаменационной комиссии.\n4. Члены экзаменационной комиссии не могут входить в составы экзаменационных комиссий разного уровня и в состав квалификационной коллегии судей равного уровня.\n5. Члены экзаменационной комиссии - представители образовательных организаций высшего образования, научных организаций, общероссийских общественных объединений юристов при осуществлении своих полномочий не связаны решениями этих учреждений, организаций и общественных объединений, и отзыв членов экзаменационной комиссии не допускается.\n6. Члены экзаменационных комиссий субъектов Российской Федерации избираются конференциями судей субъектов Российской Федерации в количестве и порядке, которые определяются конференциями судей в соответствии с их регламентами, с учетом необходимости представительства в этих комиссиях судей соответственно верховных судов республик, краевых, областных судов, судов городов федерального значения, суда автономной области, судов автономных округов, арбитражных судов субъектов Российской Федерации, районных судов, а также преподавателей юридических дисциплин образовательных организаций высшего образования, научных работников, имеющих ученую степень кандидата юридических наук или доктора юридических наук, и представителей общероссийских общественных объединений юристов.\n7. От судей арбитражных судов члены экзаменационной комиссии города Санкт-Петербурга по приему квалификационного экзамена на должность судьи избираются из числа судей Арбитражного суда города Санкт-Петербурга и Ленинградской области.\n8. Делегаты Всероссийского съезда судей избирают членов Высшей экзаменационной комиссии тайным голосованием. Избрание осуществляется:\n1) в отношении судей - на раздельных собраниях делегатов от судей Верховного Суда Российской Федерации, от судей судов общей юрисдикции и от судей арбитражных судов по представлению Председателя Верховного Суда Российской Федерации. Избранными считаются судьи, получившие наибольшее количество голосов делегатов, принявших участие в голосовании, при условии, что в голосовании принимали участие более половины делегатов съезда от судей соответствующих судов; (В редакции Федерального закона от 02.06.2016 № 168-ФЗ)\n2) в отношении иных членов комиссии - по представлению Председателя Верховного Суда Российской Федерации, которое основано на поступивших ему на рассмотрение предложениях образовательных организаций высшего образования, научных организаций, общероссийских общественных объединений юристов.\n9. Делегаты конференций судей субъектов Российской Федерации избирают членов экзаменационных комиссий субъектов Российской Федерации тайным голосованием. Избрание осуществляется:\n1) в отношении судей - по представлению председателя верховного суда республики, краевого, областного суда, суда города федерального значения, суда автономной области, суда автономного округа и по представлению председателя арбитражного суда субъекта Российской Федерации;\n2) в отношении иных членов экзаменационных комиссий субъектов Российской Федерации - по представлению председателя верховного суда республики, краевого, областного суда, суда города федерального значения, суда автономной области, суда автономного округа и по представлению председателя арбитражного суда субъекта Российской Федерации, которые основаны на поступивших им на рассмотрение предложениях образовательных организаций высшего образования, научных организаций, общероссийских общественных объединений юристов.\n10. Председатель Верховного Суда Российской Федерации, председатель верховного суда республики, краевого, областного суда, суда города федерального значения, суда автономной области, суда автономного округа, председатель арбитражного суда субъекта Российской Федерации представляют не менее двух кандидатур на каждое место члена экзаменационной комиссии.\n11. Порядок представления кандидатур в состав экзаменационных комиссий устанавливается регламентами Всероссийского съезда судей и конференций судей субъектов Российской Федерации, а в случаях, предусмотренных пунктом 13 настоящей статьи, - регламентами Совета судей Российской Федерации и советов судей субъектов Российской Федерации.\n12. Полномочия члена экзаменационной комиссии из числа судей могут быть досрочно прекращены по его инициативе, либо в случае совершения им дисциплинарного проступка, либо в случае прекращения полномочий судьи, либо в случае его отсутствия на заседаниях экзаменационной комиссии в течение четырех месяцев без уважительных причин. Полномочия иного члена экзаменационной комиссии могут быть досрочно прекращены по его инициативе, либо в случае совершения им преступления, установленного вступившим в законную силу приговором суда, либо в случае его отсутствия на заседаниях экзаменационной комиссии в течение четырех месяцев без уважительных причин. Решение о досрочном прекращении полномочий члена экзаменационной комиссии принимается съездом (конференцией) судей, а в период между съездами (конференциями) судей - соответствующим советом судей. В случае досрочного прекращения полномочий члена экзаменационной комиссии избрание в состав экзаменационной комиссии другого лица осуществляется соответствующим советом судей на срок до истечения полномочий экзаменационной комиссии. Представления о досрочном прекращении полномочий члена экзаменационной комиссии и об избрании в состав экзаменационной комиссии другого лица в период между съездами (конференциями) судей вносятся в соответствующий совет судей председателями судов, указанными в пункте 10 настоящей статьи.\nРешение о досрочном прекращении полномочий члена Высшей экзаменационной комиссии в период между всероссийскими съездами судей принимается Советом судей Российской Федерации. В случае досрочного прекращения полномочий члена Высшей экзаменационной комиссии избрание в состав Высшей экзаменационной комиссии другого лица в период между всероссийскими съездами судей осуществляется Советом судей Российской Федерации на срок до истечения полномочий Высшей экзаменационной комиссии.\nПредставления о досрочном прекращении полномочий члена Высшей экзаменационной комиссии и об избрании в состав Высшей экзаменационной комиссии другого лица в период между всероссийскими съездами судей вносятся в Совет судей Российской Федерации Председателем Верховного Суда Российской Федерации.\n13. Экзаменационные комиссии избирают из числа своих членов председателя экзаменационной комиссии и заместителя (заместителей) председателя экзаменационной комиссии. Секретарь экзаменационной комиссии назначается Судебным департаментом при Верховном Суде Российской Федерации или органом, входящим в его систему, по представлению соответствующей экзаменационной комиссии. Секретарь экзаменационной комиссии в принятии решений экзаменационной комиссии не участвует.\n(Дополнение статьей - Федеральный закон от 03.12.2011 № 388-ФЗ) (В редакции Федерального закона от 06.04.2015 № 69-ФЗ)"],
["12","Общие собрания судей судов","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","","Статья 12. Общие собрания судей судов\nДля обсуждения вопросов, связанных с совершенствованием организации работы суда, выражения законных интересов судей, а также для проведения в случаях, установленных настоящим Федеральным законом, выборов делегатов на съезд (конференцию) судей в каждом суде не реже чем один раз в год могут созываться общие собрания судей. По решению общего собрания может быть избран совет судей данного суда."],
["13","Срок полномочий выборных органов судейского сообщества","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2026-05-02","Статья 13. Срок полномочий выборных органов судейского сообщества\n1. Совет судей Российской Федерации, советы судей субъектов Российской Федерации, Высшая квалификационная коллегия судей Российской Федерации, квалификационные коллегии судей субъектов Российской Федерации, Высшая экзаменационная комиссия и экзаменационные комиссии субъектов Российской Федерации избираются на шесть лет. (В редакции федеральных законов от 03.12.2011 № 388-ФЗ, от 02.05.2026 № 122-ФЗ)\n2. По истечении указанных сроков полномочия выборных органов судейского сообщества сохраняются до проведения очередных съезда, конференций и общих собраний судей."],
["14","Регламенты работы органов судейского сообщества","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2011-12-03","Статья 14. Регламенты работы органов судейского сообщества\n1. Регламент работы Всероссийского съезда судей и регламент проведения заседаний Совета судей Российской Федерации утверждаются Всероссийским съездом судей.\n2. Регламент работы конференций судей и регламенты проведения заседаний советов судей субъектов Российской Федерации утверждаются конференциями судей субъектов Российской Федерации.\n3. Квалификационные коллегии судей осуществляют свою деятельность в соответствии с положением о порядке работы квалификационных коллегий судей, утверждаемым Высшей квалификационной коллегией судей Российской Федерации.\n4. Организация работы Высшей экзаменационной комиссии, экзаменационных комиссий субъектов Российской Федерации регулируется соответствующими регламентами, утверждаемыми Высшей экзаменационной комиссией. (Дополнение пунктом - Федеральный закон от 03.12.2011 № 388-ФЗ)"],
["15","Запросы, обращения и решения органов судейского сообщества и срок их рассмотрения","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2015-04-06","Статья 15. Запросы, обращения и решения органов судейского сообщества и срок их рассмотрения\n1. Советы судей, квалификационные коллегии судей и экзаменационные комиссии вправе запрашивать у государственных органов, общественных объединений и должностных лиц и получать от них сведения и документы, необходимые для их деятельности. (В редакции Федерального закона от 06.04.2015 № 69-ФЗ)\n2. Запросы, обращения и решения органов судейского сообщества подлежат рассмотрению в месячный срок со дня их поступления в государственные органы, общественные объединения и к должностным лицам."],
["16","Взаимодействие органов судейского сообщества","ГЛАВА I. СУДЕЙСКОЕ СООБЩЕСТВО В РОССИЙСКОЙ ФЕДЕРАЦИИ И ОРГАНЫ СУДЕЙСКОГО СООБЩЕСТВА","2011-12-03","Статья 16. Взаимодействие органов судейского сообщества\n1. Советы судей, квалификационные коллегии судей и экзаменационные комиссии обмениваются необходимой информацией о своей деятельности.\n2. Совет судей Российской Федерации и Президиум Совета судей Российской Федерации, Высшая квалификационная коллегия судей Российской Федерации и Президиум Высшей квалификационной коллегии судей Российской Федерации, Высшая экзаменационная комиссия направляют необходимую информацию о своей деятельности соответственно в советы судей субъектов Российской Федерации, квалификационные коллегии судей субъектов Российской Федерации и в экзаменационные комиссии субъектов Российской Федерации.\n3. Советы судей субъектов Российской Федерации, квалификационные коллегии судей субъектов Российской Федерации и экзаменационные комиссии субъектов Российской Федерации информируют о своей деятельности соответственно Совет судей Российской Федерации, Высшую квалификационную коллегию судей Российской Федерации и Высшую экзаменационную комиссию.\n(Статья в редакции Федерального закона от 03.12.2011 № 388-ФЗ)"],
["17","Полномочия Высшей квалификационной коллегии судей Российской Федерации","ГЛАВА II. ПОЛНОМОЧИЯ КВАЛИФИКАЦИОННЫХ КОЛЛЕГИЙ СУДЕЙ","2020-12-08","Статья 17. Полномочия Высшей квалификационной коллегии судей Российской Федерации\n1. Высшая квалификационная коллегия судей Российской Федерации рассматривает вопросы, отнесенные к ее компетенции федеральными конституционными законами, федеральными законами, и принимает мотивированные решения.\n2. Высшая квалификационная коллегия судей Российской Федерации:\n1) рассматривает заявления кандидатов на должность Председателя Верховного Суда Российской Федерации и представляет Президенту Российской Федерации свои заключения; (В редакции Федерального закона от 12.03.2014 № 29-ФЗ)\n2) рассматривает заявления кандидатов на должности первого заместителя Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации - председателей судебных коллегий Верховного Суда Российской Федерации (далее - заместители Председателя Верховного Суда Российской Федерации), председателя Апелляционной коллегии Верховного Суда Российской Федерации, заместителя председателя Апелляционной коллегии Верховного Суда Российской Федерации, судей Верховного Суда Российской Федерации, председателей, заместителей председателей других федеральных судов (за исключением районных судов), а также судей кассационных судов общей юрисдикции, апелляционных судов общей юрисдикции, арбитражных судов округов, арбитражных апелляционных судов, Суда по интеллектуальным правам, военных судов и представляет Председателю Верховного Суда Российской Федерации свои заключения; (В редакции федеральных законов от 12.03.2014 № 29-ФЗ; от 29.07.2018 № 266-ФЗ)\n2.1) рассматривает предложения Председателя Верховного Суда Российской Федерации, касающиеся представления Президенту Российской Федерации кандидатур судей Верховного Суда Российской Федерации для назначения в установленном порядке на должность члена Президиума Верховного Суда Российской Федерации, и представляет Председателю Верховного Суда Российской Федерации свои заключения; (Дополнение подпунктом - Федеральный закон от 14.08.2004 № 100-ФЗ) (В редакции Федерального закона от 12.03.2014 № 29-ФЗ)\n2.2) проводит в обязательном порядке проверки опубликованных в средствах массовой информации сведений о поведении судьи, не соответствующем требованиям, предъявляемым кодексом судейской этики, и подрывающем авторитет судебной власти, если заключение о рекомендации на должность судьи давалось этой коллегией; (Дополнение подпунктом - Федеральный закон от 25.12.2008 № 274-ФЗ)\n3) объявляет в средствах массовой информации об открытии вакантных должностей Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации, судей Верховного Суда Российской Федерации, председателей, заместителей председателей других федеральных судов (за исключением районных судов), а также судей кассационных судов общей юрисдикции, апелляционных судов общей юрисдикции, арбитражных судов округов, арбитражных апелляционных судов, Суда по интеллектуальным правам, военных судов с указанием времени и места приема и рассмотрения документов; (В редакции федеральных законов от 12.03.2014 № 29-ФЗ; от 29.07.2018 № 266-ФЗ)\n4) приостанавливает, возобновляет либо прекращает полномочия (за исключением прекращения полномочий судей, достигших предельного возраста пребывания в должности судьи), а также приостанавливает, возобновляет либо прекращает отставку Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации, судей Верховного Суда Российской Федерации, председателей, заместителей председателей других федеральных судов (за исключением районных судов), а также судей кассационных судов общей юрисдикции, апелляционных судов общей юрисдикции, арбитражных судов округов, арбитражных апелляционных судов, Суда по интеллектуальным правам, военных судов, членов Совета судей Российской Федерации и Высшей квалификационной коллегии судей Российской Федерации, председателей советов судей и квалификационных коллегий судей субъектов Российской Федерации и их заместителей; (В редакции федеральных законов от 12.03.2014 № 29-ФЗ; от 29.07.2018 № 266-ФЗ)\n5) осуществляет квалификационную аттестацию судей Верховного Суда Российской Федерации, председателей, заместителей председателей федеральных судов (за исключением Верховного Суда Российской Федерации и районных судов), а также судей кассационных судов общей юрисдикции, апелляционных судов общей юрисдикции, арбитражных судов округов, арбитражных апелляционных судов, Суда по интеллектуальным правам и военных судов; (В редакции федеральных законов от 12.03.2014 № 29-ФЗ; от 29.07.2018 № 266-ФЗ)\n6) дает заключения о возможности привлечения судей, пребывающих в отставке, к исполнению обязанностей судей Верховного Суда Российской Федерации, кассационных судов общей юрисдикции, апелляционных судов общей юрисдикции, арбитражных судов округов, арбитражных апелляционных судов, Суда по интеллектуальным правам и военных судов; (В редакции федеральных законов от 12.03.2014 № 29-ФЗ; от 29.07.2018 № 266-ФЗ)\n7) присваивает судьям первый и высший квалификационные классы;\n8) налагает дисциплинарные взыскания на судей Верховного Суда Российской Федерации, председателей, заместителей председателей федеральных судов (за исключением районных судов), а также на судей кассационных судов общей юрисдикции, апелляционных судов общей юрисдикции, арбитражных судов округов, арбитражных апелляционных судов, Суда по интеллектуальным правам и военных судов, членов Совета судей Российской Федерации и Высшей квалификационной коллегии судей Российской Федерации, председателей, заместителей председателей советов судей и квалификационных коллегий судей субъектов Российской Федерации за совершение ими дисциплинарного проступка; (В редакции федеральных законов от 12.03.2014 № 29-ФЗ; от 29.07.2018 № 266-ФЗ)\n9) утверждает положение о порядке работы квалификационных коллегий судей;\n10) рассматривает вопросы, отнесенные к компетенции квалификационных коллегий судей субъектов Российской Федерации, в случае невозможности их разрешения этими коллегиями;\n10.1) рассматривает жалобы на решения квалификационных коллегий судей субъектов Российской Федерации. Если по результатам рассмотрения жалобы на решение о привлечении судьи к дисциплинарной ответственности Высшая квалификационная коллегия судей Российской Федерации придет к выводу о том, что дисциплинарное взыскание, наложенное на судью квалификационной коллегией судей субъекта Российской Федерации, несоразмерно тяжести совершенного дисциплинарного проступка, она вправе изменить вид дисциплинарного взыскания; (Дополнение подпунктом - Федеральный закон от 25.12.2008 № 274-ФЗ) (В редакции Федерального закона от 03.07.2019 № 163-ФЗ)\n11) знакомится с работой квалификационных коллегий судей субъектов Российской Федерации, заслушивает сообщения их председателей о проделанной работе и дает рекомендации, направленные на совершенствование деятельности указанных коллегий; изучает и обобщает практику работы квалификационных коллегий судей, организует учебу членов этих коллегий;\n12) принимает решения о представлении судей к награждению государственными наградами Российской Федерации и присвоении им почетных званий Российской Федерации;\n13) осуществляет иные полномочия, предусмотренные федеральными конституционными законами и федеральными законами.\n2.1. При внесении Президентом Российской Федерации в Совет Федерации Федерального Собрания Российской Федерации представления о прекращении полномочий Председателя Верховного Суда Российской Федерации, заместителей Председателя Верховного Суда Российской Федерации, судей Верховного Суда Российской Федерации, председателей, заместителей председателей и судей кассационных судов общей юрисдикции, апелляционных судов общей юрисдикции, кассационного военного суда, апелляционного военного суда, арбитражных судов округов, арбитражных апелляционных судов, Суда по интеллектуальным правам в случае совершения ими поступка, порочащего честь и достоинство судьи, а также в иных предусмотренных федеральным конституционным законом случаях, свидетельствующих о невозможности осуществления судьей своих полномочий, рассмотрение Высшей квалификационной коллегией судей Российской Федерации заявления судьи о прекращении его полномочий по другим основаниям приостанавливается до рассмотрения по существу указанного вопроса Советом Федерации Федерального Собрания Российской Федерации. (Дополнение пунктом - Федеральный закон от 08.12.2020 № 426-ФЗ)\n3. Высшая квалификационная коллегия судей Российской Федерации может осуществлять свои полномочия, если ее состав сформирован не менее чем на две трети."],
["18","Президиум Высшей квалификационной коллегии судей Российской Федерации","ГЛАВА II. ПОЛНОМОЧИЯ КВАЛИФИКАЦИОННЫХ КОЛЛЕГИЙ СУДЕЙ","2008-12-25","Статья 18. Президиум Высшей квалификационной коллегии судей Российской Федерации\n1. Президиум Высшей квалификационной коллегии судей Российской Федерации состоит из председателя указанной коллегии и трех его заместителей, избираемых Высшей квалификационной коллегией судей Российской Федерации из числа ее членов.\n2. Президиум Высшей квалификационной коллегии судей Российской Федерации является рабочим органом этой коллегии, ей подотчетен и образуется для оперативного решения вопросов, связанных с организацией работы Высшей квалификационной коллегии судей Российской Федерации.\n3. Для обеспечения деятельности и организации работы Высшей квалификационной коллегии судей Российской Федерации создается аппарат, который является структурным подразделением Судебного департамента при Верховном Суде Российской Федерации. (Дополнение пунктом - Федеральный закон от 25.12.2008 № 274-ФЗ)"],
["19","Полномочия квалификационных коллегий судей субъектов Российской Федерации","ГЛАВА II. ПОЛНОМОЧИЯ КВАЛИФИКАЦИОННЫХ КОЛЛЕГИЙ СУДЕЙ","2020-12-08","Статья 19. Полномочия квалификационных коллегий судей субъектов Российской Федерации\n1. Квалификационные коллегии судей субъектов Российской Федерации рассматривают вопросы, отнесенные к их компетенции федеральными конституционными законами, федеральными законами, и принимают мотивированные решения в отношении судей верховных судов республик, краевых, областных судов, судов городов федерального значения, суда автономной области и судов автономных округов, арбитражных судов субъектов Российской Федерации, мировых судей, судей районных судов (в том числе председателей и заместителей председателей районных судов). (В редакции федеральных законов от 28.11.2009 № 296-ФЗ, от 08.12.2020 № 426-ФЗ)\n2. Квалификационные коллегии судей субъектов Российской Федерации:\n1) рассматривают заявления лиц, претендующих на соответствующую должность судьи, и с учетом результатов квалификационного экзамена дают заключения о рекомендации данных лиц на должность судьи либо об отказе в такой рекомендации;\n1.1) (Дополнение подпунктом - Федеральный закон от 14.08.2004 № 100-ФЗ) (Утратил силу - Федеральный закон от 03.07.2019 № 163-ФЗ)\n1.2) рассматривают представления председателей верховных судов республик, краевых, областных судов, судов городов федерального значения, суда автономной области и судов автономных округов об утверждении председателей судебных коллегий по гражданским делам, по уголовным делам, иных судебных коллегий и представляют свои заключения Председателю Верховного Суда Российской Федерации, который утверждает председателей указанных коллегий; (Дополнение подпунктом - Федеральный закон от 14.08.2004 № 100-ФЗ)\n1.3) проводит в обязательном порядке проверки опубликованных в средствах массовой информации сведений о поведении судьи, не соответствующем требованиям, предъявляемым кодексом судейской этики, и подрывающем авторитет судебной власти, если заключение о рекомендации на должность судьи давалось этой коллегией; (Дополнение подпунктом - Федеральный закон от 25.12.2008 № 274-ФЗ)\n2) (Подпункт утратил силу Федерального закона от 03.12.2011 № 388-ФЗ)\n3) объявляют в средствах массовой информации об открытии вакантных должностей председателей, заместителей председателей районных судов, а также судей соответствующих федеральных судов с указанием времени и места приема и рассмотрения документов;\n4) организуют проверку достоверности биографических и иных сведений, представленных кандидатами на вакантные должности, при необходимости запрашивают по основаниям и в порядке, которые предусмотрены законодательством Российской Федерации, у органов, осуществляющих оперативно-розыскную деятельность, и других государственных органов данные, необходимые для принятия решения по заявлению о рекомендации на вакантную должность судьи; (В редакции Федерального закона от 25.12.2008 № 274-ФЗ)\n5) приостанавливают, возобновляют либо прекращают полномочия (за исключением прекращения полномочий судей, достигших предельного возраста пребывания в должности судьи), а также приостанавливают, возобновляют либо прекращают отставку судей соответствующих федеральных судов (за исключением лиц, указанных в подпункте 4 пункта 2 статьи 17 настоящего Федерального закона), председателей и заместителей председателей районных судов, членов соответствующих советов судей и квалификационных коллегий судей субъектов Российской Федерации; (В редакции федеральных законов от 05.04.2005 № 33-ФЗ; от 17.07.2009 № 157-ФЗ; от 09.11.2009 № 246-ФЗ)\n6) осуществляют квалификационную аттестацию судей соответствующих судов, а также мировых судей, председателей и заместителей председателей районных судов; присваивают судьям соответствующих судов, а также мировым судьям, председателям и заместителям председателей районных судов квалификационные классы (за исключением первого и высшего);\n7) дают заключения о возможности привлечения судей, пребывающих в отставке, к исполнению обязанностей судей соответствующих федеральных судов, мировых судей, а также председателей и заместителей председателей районных судов; (В редакции Федерального закона от 04.03.2013 № 20-ФЗ)\n8) налагают дисциплинарные взыскания на судей соответствующих судов (в том числе на председателей и заместителей председателей районных судов) за совершение ими дисциплинарного проступка;\n9) осуществляют иные полномочия в соответствии с федеральными конституционными законами и федеральными законами.\n3. Квалификационные коллегии судей субъектов Российской Федерации могут осуществлять свои полномочия, если их составы сформированы не менее чем на две трети."],
["20","Пересмотр решений по вновь открывшимся обстоятельствам","ГЛАВА II. ПОЛНОМОЧИЯ КВАЛИФИКАЦИОННЫХ КОЛЛЕГИЙ СУДЕЙ","2004-08-14","Статья 20. Пересмотр решений по вновь открывшимся обстоятельствам\n1. Квалификационная коллегия судей вправе пересмотреть ранее принятое решение по вновь открывшимся обстоятельствам.\nХодатайство о пересмотре указанного решения по вновь открывшимся обстоятельствам может быть подано в квалификационную коллегию судей кандидатом на должность судьи или судьей, в отношении которых принято решение, а также должностным лицом, по представлению которого принято решение, председателем соответствующего или вышестоящего суда. Квалификационная коллегия судей вправе пересмотреть свое решение при отсутствии указанного ходатайства в случае, если вновь открывшиеся обстоятельства не позволяют признать ранее принятое решение законным и обоснованным. (В редакции Федерального закона от 14.08.2004 № 100-ФЗ)\n2. Основаниями для пересмотра решения по вновь открывшимся обстоятельствам являются такие обстоятельства, которые не были известны квалификационной коллегии судей и сами по себе или вместе с ранее установленными обстоятельствами дают основание для принятия другого решения."],
["21","Порядок рассмотрения квалификационными коллегиями судей представленных материалов","ГЛАВА III. ПРОИЗВОДСТВО В КВАЛИФИКАЦИОННЫХ КОЛЛЕГИЯХ СУДЕЙ","","Статья 21. Порядок рассмотрения квалификационными коллегиями судей представленных материалов\n1. Подготовку заседания квалификационной коллегии судей осуществляет председатель квалификационной коллегии судей или его заместитель, который определяет время и место проведения заседания, а также круг лиц, подлежащих приглашению на заседание.\nПриглашенные лица должны быть своевременно извещены о времени и месте проведения заседания.\n2. Судья, в отношении которого начато производство квалификационной коллегией судей, вправе ознакомиться с имеющимися в квалификационной коллегии судей материалами и представить свои возражения и замечания.\n3. О времени и месте проведения заседания квалификационной коллегии судей судья, в отношении которого начато производство, извещается в срок, необходимый для явки на заседание.\n4. В случае неявки без уважительной причины на заседание квалификационной коллегии судей судьи, извещенного надлежащим образом о времени и месте проведения заседания, квалификационная коллегия судей рассматривает вопрос в его отсутствие.\nПри рассмотрении материала о дисциплинарной ответственности судьи, привлечении судьи к уголовной ответственности решением квалификационной коллегии судей полномочия судьи могут быть приостановлены до принятия решения по существу вопроса. Указанное решение может быть принято в отсутствие судьи, в том числе в случае его отсутствия по уважительной причине.\n5. Член квалификационной коллегии судей с ее согласия может не участвовать в рассмотрении конкретного материала. Член квалификационной коллегии судей, принявший участие в ее заседании, не вправе воздержаться от голосования.\n6. В заседаниях квалификационных коллегий судей могут участвовать и высказывать свое мнение по обсуждаемым вопросам председатели и заместители председателей судов, руководители Судебного департамента при Верховном Суде Российской Федерации и входящих в его систему органов, председатели и заместители председателей советов судей, других квалификационных коллегий судей или их представители."],
["22","Особенности рассмотрения представлений и обращений о совершении судьей дисциплинарного проступка","ГЛАВА III. ПРОИЗВОДСТВО В КВАЛИФИКАЦИОННЫХ КОЛЛЕГИЯХ СУДЕЙ","2018-07-29","Статья 22. Особенности рассмотрения представлений и обращений о совершении судьей дисциплинарного проступка\n1. Обращение органа судейского сообщества о наложении на судью дисциплинарного взыскания в связи с совершением им дисциплинарного проступка рассматривается квалификационной коллегией судей при наличии в представленных материалах сведений, подтверждающих обстоятельства совершения этого проступка, письменных объяснений судьи и представленных им доказательств, подтверждающих эти объяснения, либо данных об отказе судьи от дачи таких объяснений и данных, характеризующих судью. (В редакции Федерального закона от 29.07.2018 № 243-ФЗ)\nКвалификационная коллегия судей в пределах своих полномочий может провести дополнительную проверку представленных материалов, запросить дополнительные материалы и заслушать объяснения соответствующих лиц об обстоятельствах совершения судьей дисциплинарного проступка.\n2. Жалобы и сообщения, содержащие сведения о совершении судьей дисциплинарного проступка, поступившие в квалификационную коллегию судей от органов (кроме органов судейского сообщества), а также от граждан и должностных лиц, рассматриваются квалификационной коллегией судей самостоятельно.\nДля проведения проверки сведений, содержащихся в указанных жалобах и сообщениях, квалификационная коллегия судей может образовать комиссию из числа членов совета судей и членов квалификационной коллегии судей, а также представителей общественности и сотрудников аппарата квалификационной коллегии судей. Результаты проверки докладываются комиссией на заседании квалификационной коллегии судей, которая принимает решение по существу.\n(Пункт в редакции Федерального закона от 29.07.2018 № 243-ФЗ)\n3. В случае постановки вопроса о досрочном прекращении полномочий судьи в связи с совершением им дисциплинарного проступка либо наличием данных о совершении им указанного проступка, требующих дополнительной проверки, рассмотрение заявления судьи о прекращении его полномочий по другим основаниям приостанавливается до рассмотрения по существу указанного вопроса. (В редакции Федерального закона от 02.10.2012 № 165-ФЗ)"],
["23","Порядок принятия решений квалификационными коллегиями судей","ГЛАВА III. ПРОИЗВОДСТВО В КВАЛИФИКАЦИОННЫХ КОЛЛЕГИЯХ СУДЕЙ","2009-07-24","Статья 23. Порядок принятия решений квалификационными коллегиями судей\n1. Квалификационная коллегия судей правомочна принять решение, если на ее заседании присутствуют более половины членов квалификационной коллегии судей.\nРешение считается принятым, если за него проголосовали более половины членов квалификационной коллегии судей, принимавших участие в заседании.\nРешение о прекращении либо приостановлении полномочий судьи или его отставке считается принятым, если за него проголосовали не менее двух третей членов квалификационной коллегии судей, принимавших участие в заседании.\n2. Голосование и принятие решения проводятся в отсутствие судьи, в отношении которого рассматривается вопрос, а также в отсутствие приглашенных и иных лиц. Член квалификационной коллегии судей вправе изложить в письменном виде свое особое мнение, которое прилагается к протоколу заседания квалификационной коллегии судей.\n2.1. Решение по результатам рассмотрения вопроса о досрочном прекращении полномочий судьи в связи с совершением им дисциплинарного проступка или вопроса о прекращении отставки судьи в связи с осуществлением им деятельности, не совместимой с должностью судьи, либо совершением поступков, его порочащих, принимается тайным голосованием членов квалификационной коллегии судей. Порядок тайного голосования устанавливается положением о порядке работы квалификационных коллегий судей. (Дополнение пунктом - Федеральный закон от 24.07.2009 № 210-ФЗ)\n2.2. В случае принятия квалификационной коллегией судей решения о досрочном прекращении полномочий судьи в связи с совершением им дисциплинарного проступка или решения о прекращении отставки судьи в связи с осуществлением им деятельности, не совместимой с должностью судьи, либо совершением поступков, его порочащих, в каждом из решений должны быть указаны мотивы его принятия. (Дополнение пунктом - Федеральный закон от 24.07.2009 № 210-ФЗ)\n3. Решение квалификационной коллегии судей подписывается председательствующим на заседании и секретарем квалификационной коллегии судей. При отсутствии секретаря квалификационной коллегии судей коллегия принимает решение временно возложить его обязанности на одного из членов коллегии."],
["24","Протокол заседания квалификационной коллегии судей","ГЛАВА III. ПРОИЗВОДСТВО В КВАЛИФИКАЦИОННЫХ КОЛЛЕГИЯХ СУДЕЙ","","Статья 24. Протокол заседания квалификационной коллегии судей\n1. На заседании квалификационной коллегии судей по каждому рассматриваемому вопросу ведется отдельный протокол, в котором отражаются все необходимые сведения о ходе заседания. Протокол подписывается председательствующим на заседании и секретарем коллегии.\n2. Лицо, в отношении которого рассмотрен вопрос, и лицо, внесшее представление, в течение трех дней после получения извещения о подписании протокола заседания квалификационной коллегии судей вправе письменно обратиться в квалификационную коллегию судей с просьбой об ознакомлении с указанным протоколом, ознакомиться с ним и подать свои замечания. Указанные замечания подлежат приобщению к протоколу заседания квалификационной коллегии судей.\n3. Секретарем Высшей квалификационной коллегии судей Российской Федерации является штатный работник Судебного департамента при Верховном Суде Российской Федерации, а секретарями квалификационных коллегий судей субъектов Российской Федерации - штатные работники входящих в его систему органов в субъектах Российской Федерации."],
["25","Сроки рассмотрения материалов квалификационными коллегиями судей","ГЛАВА III. ПРОИЗВОДСТВО В КВАЛИФИКАЦИОННЫХ КОЛЛЕГИЯХ СУДЕЙ","","Статья 25. Сроки рассмотрения материалов квалификационными коллегиями судей\nПоступившие материалы должны быть рассмотрены Высшей квалификационной коллегией судей Российской Федерации не позднее трех месяцев, а квалификационными коллегиями судей субъектов Российской Федерации - не позднее одного месяца со дня их поступления в коллегию, если иные сроки не установлены федеральными законами."],
["26","Обжалование решений квалификационных коллегий судей","ГЛАВА III. ПРОИЗВОДСТВО В КВАЛИФИКАЦИОННЫХ КОЛЛЕГИЯХ СУДЕЙ","2018-07-29","Статья 26. Обжалование решений квалификационных коллегий судей\n1. Решение, принятое квалификационной коллегией судей, может быть обжаловано в судебном порядке либо в Высшую квалификационную коллегию судей Российской Федерации (в отношении решений квалификационных коллегий судей субъектов Российской Федерации) лицом, в отношении которого оно принято.\n2. Решения Высшей квалификационной коллегии судей Российской Федерации и квалификационных коллегий судей субъектов Российской Федерации о приостановлении либо прекращении полномочий судей, привлечении их к дисциплинарной ответственности, приостановлении либо прекращении отставки судей, а также об отказе в рекомендации на должности судей могут быть обжалованы заинтересованными лицами в течение десяти дней со дня получения копии соответствующего решения, за исключением случаев, предусмотренных пунктом 5 настоящей статьи. (В редакции Федерального закона от 02.10.2012 № 165-ФЗ)\n3. Решения квалификационных коллегий судей субъектов Российской Федерации об отказе в рекомендации на должности судей, о привлечении судей к дисциплинарной ответственности (за исключением решений о досрочном прекращении полномочий судей за совершение ими дисциплинарных проступков), приостановлении отставки судей могут быть обжалованы в соответствующие верховные суды республик, краевые, областные суды, суды городов федерального значения, суд автономной области и суды автономных округов. (В редакции Федерального закона от 12.03.2014 № 29-ФЗ)\n4. Решения квалификационных коллегий судей субъектов Российской Федерации о прекращении полномочий судей либо о прекращении их отставки могут быть обжалованы в Верховный Суд Российской Федерации. (В редакции Федерального закона от 12.03.2014 № 29-ФЗ)\n5. Решения Высшей квалификационной коллегии судей Российской Федерации об отказе в рекомендации на должности судей, о привлечении судей к дисциплинарной ответственности, приостановлении либо прекращении полномочий судей, приостановлении либо прекращении их отставки могут быть обжалованы в Верховный Суд Российской Федерации. (В редакции Федерального закона от 12.03.2014 № 29-ФЗ)\n5.1. (Дополнение пунктом - Федеральный закон от 12.03.2014 № 29-ФЗ) (Утратил силу - Федеральный закон от 29.07.2018 № 243-ФЗ)\n6. Иные решения квалификационных коллегий судей могут быть обжалованы в установленном пунктами 1 и 2 настоящей статьи порядке только по мотивам нарушения процедуры их вынесения.\n7. Решения квалификационных коллегий судей вступают в силу с момента их оглашения. Решения квалификационных коллегий судей оглашаются непосредственно после принятия.\n(Статья в редакции Федерального закона от 09.11.2009 № 246-ФЗ)"],
["26.1","Полномочия экзаменационных комиссий","ГЛАВА III.1. ПОЛНОМОЧИЯ ЭКЗАМЕНАЦИОННЫХ КОМИССИЙ И ПОРЯДОК ПРОВЕДЕНИЯ ЭКЗАМЕНА","2015-04-06","Статья 26.1. Полномочия экзаменационных комиссий\n1. Высшая экзаменационная комиссия принимает экзамены у кандидата на должность судьи в случае, если заключение о рекомендации кандидата на эту должность относится к полномочиям Высшей квалификационной коллегии судей Российской Федерации.\n2. Экзаменационная комиссия субъекта Российской Федерации принимает экзамены у кандидата на должность судьи в случае, если заключение о рекомендации кандидата на эту должность относится к полномочиям квалификационной коллегии судей данного субъекта Российской Федерации. (В редакции Федерального закона от 06.04.2015 № 69-ФЗ)\n3. Высшая экзаменационная комиссия осуществляет общее и методическое руководство экзаменационными комиссиями субъектов Российской Федерации. Высшая экзаменационная комиссия дает разъяснения экзаменационным комиссиям субъектов Российской Федерации по вопросам, связанным с приемом квалификационного экзамена на должность судьи. (В редакции Федерального закона от 06.04.2015 № 69-ФЗ)\n4. Высшая экзаменационная комиссия утверждает регламенты экзаменационных комиссий."],
["26.2","Организация работы экзаменационных комиссий","ГЛАВА III.1. ПОЛНОМОЧИЯ ЭКЗАМЕНАЦИОННЫХ КОМИССИЙ И ПОРЯДОК ПРОВЕДЕНИЯ ЭКЗАМЕНА","","Статья 26.2. Организация работы экзаменационных комиссий\n1. Работу экзаменационной комиссии организует председатель экзаменационной комиссии или по его поручению заместитель председателя экзаменационной комиссии либо член экзаменационной комиссии.\n2. Экзаменационная комиссия правомочна принимать квалификационный экзамен на должность судьи при наличии не менее половины ее состава. При этом судьи должны составлять не менее половины от числа присутствующих на квалификационном экзамене членов комиссии."],
["26.3","Порядок проведения квалификационного экзамена на должность судьи и порядок определения оценки знаний кандидата на должность судьи","ГЛАВА III.1. ПОЛНОМОЧИЯ ЭКЗАМЕНАЦИОННЫХ КОМИССИЙ И ПОРЯДОК ПРОВЕДЕНИЯ ЭКЗАМЕНА","2020-12-08","Статья 26.3. Порядок проведения квалификационного экзамена на должность судьи и порядок определения оценки знаний кандидата на должность судьи\n1. Порядок проведения квалификационного экзамена на должность судьи и порядок определения оценки знаний кандидата на должность судьи устанавливаются регламентами экзаменационных комиссий, утверждаемыми Высшей экзаменационной комиссией.\n2. Экзаменационные билеты составляются отдельно для кандидатов на должность судьи суда общей юрисдикции, кандидатов на должность судьи арбитражного суда, кандидатов на должность судьи специализированного суда и должны содержать три теоретических вопроса по различным отраслям права, две задачи по вопросам судебной практики и письменное задание по подготовке процессуального документа по макету дела.\n3. Теоретические вопросы в экзаменационных билетах составляются Высшей экзаменационной комиссией, а задачи по вопросам судебной практики и письменные задания по подготовке процессуального документа по макету дела составляются соответствующими экзаменационными комиссиями и утверждаются Высшей экзаменационной комиссией.\n4. (Пункт утратил силу - Федеральный закон от 08.12.2020 № 426-ФЗ)\n5. Высшая экзаменационная комиссия составляет экзаменационные вопросы и утверждает задачи по вопросам судебной практики и письменные задания по подготовке процессуального документа по макету дела по согласованию с Верховным Судом Российской Федерации.\n6. Сведения о ходе проведения квалификационного экзамена на должность судьи и его результатах отражаются в протоколе, который подписывается председательствующим на заседании экзаменационной комиссии и секретарем экзаменационной комиссии. Подготовленные кандидатом решения задач и проект процессуального документа по макету дела приобщаются к протоколу заседания экзаменационной комиссии и хранятся в архиве экзаменационной комиссии не менее четырех лет.\n7. Выписка из протокола о сдаче кандидатом на должность судьи квалификационного экзамена предоставляется кандидату по его просьбе.\n8. Экзаменационная комиссия выдает лицу, сдавшему квалификационный экзамен на должность судьи, удостоверение о результатах квалификационного экзамена с оценками по каждому вопросу и общей итоговой оценкой. В случае получения общей итоговой неудовлетворительной оценки указанное удостоверение не выдается.\n9. Результаты квалификационного экзамена на должность судьи признаются действительными в течение трех лет со дня сдачи квалификационного экзамена. В течение указанного срока кандидат на должность судьи вправе сдать квалификационный экзамен на должность судьи суда другого уровня, другой системы, другого вида или другого субъекта Российской Федерации.\n10. Кандидат, приступивший к ответу и отказавшийся от дальнейшей сдачи квалификационного экзамена на должность судьи, а также кандидат, не сдавший квалификационного экзамена, может обратиться в эту или иную экзаменационную комиссию с заявлением о допуске к сдаче квалификационного экзамена не ранее чем через шесть месяцев со дня проведения квалификационного экзамена.\n11. Кандидату на должность судьи может быть отказано в допуске к сдаче квалификационного экзамена только по основаниям, установленным федеральным законом. В случае отказа кандидату в допуске к сдаче квалификационного экзамена на должность судьи соответствующее решение должно быть мотивировано и оформлено в письменном виде.\n(Статья в редакции Федерального закона от 06.04.2015 № 69-ФЗ)"],
["26.4","Обжалование решений экзаменационных комиссий","ГЛАВА III.1. ПОЛНОМОЧИЯ ЭКЗАМЕНАЦИОННЫХ КОМИССИЙ И ПОРЯДОК ПРОВЕДЕНИЯ ЭКЗАМЕНА","2015-04-06","Статья 26.4. Обжалование решений экзаменационных комиссий\n1. Кандидат на должность судьи может обжаловать решение экзаменационной комиссии в судебном порядке в течение десяти дней со дня получения удостоверения о результатах квалификационного экзамена на должность судьи. Решения Высшей экзаменационной комиссии обжалуются в Верховный Суд Российской Федерации. Решения экзаменационных комиссий субъектов Российской Федерации обжалуются в верховные суды республик, краевые, областные суды, суды городов федерального значения, суд автономной области и суды автономных округов.\n2. Решения экзаменационных комиссий могут быть обжалованы только по основаниям нарушения процедуры проведения квалификационного экзамена. (В редакции Федерального закона от 06.04.2015 № 69-ФЗ)\n3. Кандидат на должность судьи вправе обжаловать действия (бездействие) экзаменационной комиссии, в результате которых он не был допущен к сдаче квалификационного экзамена. (В редакции Федерального закона от 06.04.2015 № 69-ФЗ)"],
["27","Организационное обеспечение деятельности органов судейского сообщества","ГЛАВА IV. ОБЕСПЕЧЕНИЕ ДЕЯТЕЛЬНОСТИ ОРГАНОВ СУДЕЙСКОГО СООБЩЕСТВА","2015-04-06","Статья 27. Организационное обеспечение деятельности органов судейского сообщества\n1. Организационное обеспечение деятельности органов судейского сообщества осуществляется Судебным департаментом при Верховном Суде Российской Федерации и входящими в его систему органами.\n2. Совет судей Российской Федерации, Высшая квалификационная коллегия судей Российской Федерации и Высшая экзаменационная комиссия оказывают методическую помощь соответствующим органам судейского сообщества в их деятельности. (В редакции Федерального закона от 03.12.2011 № 388-ФЗ)\n3. Удостоверение председателя Высшей квалификационной коллегии судей Российской Федерации подписывается председателем Совета судей Российской Федерации.\nУдостоверения членов Высшей квалификационной коллегии судей Российской Федерации и председателей квалификационных коллегий судей субъектов Российской Федерации подписываются председателем Высшей квалификационной коллегии судей Российской Федерации.\nУдостоверения членов квалификационных коллегий судей субъектов Российской Федерации подписываются председателями соответствующих квалификационных коллегий судей.\n4. Удостоверение председателя Высшей экзаменационной комиссии подписывается председателем Совета судей Российской Федерации. Удостоверения членов Высшей экзаменационной комиссии и председателей экзаменационных комиссий субъектов Российской Федерации подписываются председателем Высшей экзаменационной комиссии. Удостоверения членов экзаменационных комиссий субъектов Российской Федерации подписываются председателями соответствующих экзаменационных комиссий. (Дополнение пунктом - Федеральный закон от 06.04.2015 № 69-ФЗ)"],
["28","Финансовое и материально-техническое обеспечение деятельности органов судейского сообщества","ГЛАВА IV. ОБЕСПЕЧЕНИЕ ДЕЯТЕЛЬНОСТИ ОРГАНОВ СУДЕЙСКОГО СООБЩЕСТВА","2011-12-03","Статья 28. Финансовое и материально-техническое обеспечение деятельности органов судейского сообщества\n1. Создание надлежащих условий для деятельности органов судейского сообщества, в том числе для содержания их аппарата, учреждения печатных изданий органов судейского сообщества, а также финансовое и материально-техническое обеспечение деятельности органов судейского сообщества возлагаются на Судебный департамент при Верховном Суде Российской Федерации и входящие в его систему органы.\n2. Финансовое и материально-техническое обеспечение деятельности Всероссийского съезда судей, Совета судей Российской Федерации и Президиума Совета судей Российской Федерации, Высшей квалификационной коллегии судей Российской Федерации и Президиума Высшей квалификационной коллегии судей Российской Федерации, Высшей экзаменационной комиссии по приему квалификационного экзамена на должность судьи возлагается на Судебный департамент при Верховном Суде Российской Федерации. (В редакции Федерального закона от 03.12.2011 № 388-ФЗ)"],
["28.1","Выплаты преподавателям юридических дисциплин образовательных организаций высшего образования и научным работникам, имеющим ученую степень по юридической специальности, представителям общероссийских общественных объединений юристов за участие в работе экзаменационных комиссий","ГЛАВА IV. ОБЕСПЕЧЕНИЕ ДЕЯТЕЛЬНОСТИ ОРГАНОВ СУДЕЙСКОГО СООБЩЕСТВА","2013-07-02","Статья 28.1. Выплаты преподавателям юридических дисциплин образовательных организаций высшего образования и научным работникам, имеющим ученую степень по юридической специальности, представителям общероссийских общественных объединений юристов за участие в работе экзаменационных комиссий\n(Наименование в редакции Федерального закона от 02.07.2013 № 185-ФЗ)\n1. Преподавателям юридических дисциплин образовательных организаций высшего образования, научным работникам, имеющим ученую степень по юридической специальности, представителям общероссийских общественных объединений юристов выплачивается вознаграждение за участие в работе экзаменационных комиссий, а также возмещаются расходы, связанные с направлением их в служебную командировку для участия в работе экзаменационных комиссий, в порядке и в размерах, устанавливаемых Правительством Российской Федерации. (В редакции Федерального закона от 02.07.2013 № 185-ФЗ)\n2. За преподавателями юридических дисциплин образовательных организаций высшего образования, научными работниками, имеющими ученую степень по юридической специальности, и представителями общероссийских общественных объединений юристов на время их участия в работе экзаменационной комиссии сохраняются гарантии и компенсации, предоставляемые по основному месту работы в соответствии с трудовым законодательством. (В редакции Федерального закона от 02.07.2013 № 185-ФЗ)\n(Дополнение статьей - Федеральный закон от 03.12.2011 № 388-ФЗ)"],
["29","Порядок вступления в силу настоящего Федерального закона","ГЛАВА V. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","2014-03-12","Статья 29. Порядок вступления в силу настоящего Федерального закона\n1. Настоящий Федеральный закон вступает в силу со дня его официального опубликования.\n2. Высшая квалификационная коллегия судей Российской Федерации, сформированная до вступления в силу настоящего Федерального закона, осуществляет свои полномочия до назначения представителей общественности и представителя Президента Российской Федерации. Члены Высшей квалификационной коллегии судей Российской Федерации, сформированной до вступления в силу настоящего Федерального закона, осуществляют свои полномочия до истечения срока, на который они были избраны, совместно с представителями общественности и представителем Президента Российской Федерации в составе сформированной в соответствии с настоящим Федеральным законом Высшей квалификационной коллегии судей Российской Федерации.\n3. Квалификационные коллегии судей Верховного Суда Российской Федерации, субъектов Российской Федерации, военных округов, групп войск и флотов, арбитражных судов, а также экзаменационные комиссии, сформированные до вступления в силу настоящего Федерального закона, продолжают осуществлять свои полномочия до образования соответствующих квалификационных коллегий судей и экзаменационных комиссий, предусмотренных настоящим Федеральным законом, но не более шести месяцев со дня вступления в силу настоящего Федерального закона. (В редакции Федерального закона от 12.03.2014 № 29-ФЗ)\n4. Совет судей Российской Федерации, избранный до вступления в силу настоящего Федерального закона, осуществляет свои полномочия до истечения срока, на который он был сформирован.\n5. Советы судей субъектов Российской Федерации, военных округов, групп войск и флотов, арбитражных судов, избранные до вступления в силу настоящего Федерального закона, продолжают осуществлять свои полномочия до избрания соответствующих советов судей субъектов Российской Федерации, предусмотренных настоящим Федеральным законом, но не более шести месяцев со дня вступления в силу настоящего Федерального закона.\n6. В течение трех месяцев со дня вступления в силу настоящего Федерального закона в субъектах Российской Федерации в порядке, установленном настоящим Федеральным законом, проводятся конференции и общие собрания судей, на которых избираются судьи в состав советов судей субъектов Российской Федерации и квалификационных коллегий судей субъектов Российской Федерации.\n7. Квалификационные коллегии судей и экзаменационные комиссии, сформированные до вступления в силу настоящего Федерального закона, передают всю документацию, в том числе архивы, вновь образованным соответствующим квалификационным коллегиям судей и экзаменационным комиссиям.\n8. Исчисление сроков полномочий членов советов судей и квалификационных коллегий судей, предусмотренных пунктами 3 и 4 статьи 8, пунктом 7 статьи 11 настоящего Федерального закона, производится исходя из того, что первым сроком полномочий является срок, на который был избран судья после вступления в силу настоящего Федерального закона.\n9. Со дня вступления в силу настоящего Федерального закона признать утратившими силу:\nУказ Президиума Верховного Совета РСФСР от 6 декабря 1989 года \"Об утверждении Положения о порядке созыва и проведения конференции судей судов РСФСР\" (Ведомости Верховного Совета РСФСР, 1989, № 50, ст. 1479);\nпункт 1 постановления Верховного Совета Российской Федерации от 13 мая 1993 года № 4960-I \"Об утверждении Положения о квалификационных коллегиях судей и Положения о квалификационной аттестации судей\" (Ведомости Съезда народных депутатов Российской Федерации и Верховного Совета Российской Федерации, 1993, № 24, ст. 856);\nпункт 10 статьи 1 Федерального закона от 16 ноября 1997 года № 144-ФЗ \"О внесении изменений и дополнений в законы и иные правовые акты Российской Федерации в связи с принятием Федерального конституционного закона \"Об арбитражных судах в Российской Федерации\" и Арбитражного процессуального кодекса Российской Федерации\" (Собрание законодательства Российской Федерации, 1997, № 47, ст. 5341).\nУстановить, что со дня вступления в силу настоящего Федерального закона Положение о квалификационной аттестации судей, утвержденное постановлением Верховного Совета Российской Федерации от 13 мая 1993 года № 4960-I \"Об утверждении Положения о квалификационных коллегиях судей и Положения о квалификационной аттестации судей\" (Ведомости Съезда народных депутатов Российской Федерации и Верховного Совета Российской Федерации, 1993, № 24, ст. 856), применяется в части, не противоречащей настоящему Федеральному закону.\nПрезидент Российской Федерации В.Путин\nМосква, Кремль 14 марта 2002 года № 30-ФЗ"]
];
